import React from "react";

function LeftSection() {
  return (
    <div className="container">
    <div className="row align-items-center">
      <div className="col-6" style={{ paddingLeft: "60px" }}>

        <img src="/Files/kite.png" style={{ width: "558px", height: "421px" }} className="img-fluid"/>
      </div>
      <div className="col-6" >
        <p>
        Our ultra-fast flagship trading platform with <br></br>streaming market data,
        advanced charts,<br></br> an elegant UI, and more. Enjoy the Kite <br></br>experience
        seamlessly on your Android and <br></br>iOS devices.
        </p>
      </div>
      </div>
    </div>
  );
}

export default LeftSection;
